const fs = require('node:fs');
const crypto = require('node:crypto');
const path = require('node:path');
function csv(file) {
  const [header, ...lines] = fs.readFileSync(file, 'utf8').trim().split(/\\r?\\n/);
  const fields = header.split(',');
  return lines.map(line => Object.fromEntries(line.split(',').map((v,i) => [fields[i],v])));
}
const pairs = csv('evidence/pairs.csv');
const reference = new Map(csv('evidence/reference.csv').map(r => [r.pair_id,r]));
const guide = new Map(csv('evidence/guide.csv').map(r => [r.pair_id,r]));
const matched = pairs.map(p => ({...p, reference:reference.get(p.pair_id), guide:guide.get(p.pair_id)}));
const eligible = matched.filter(p => p.reference.seconds.trim() "'!== '"'' && p.guide.seconds.trim() "'!== '"'' && Number.isFinite(Number(p.reference.seconds)) && Number(p.reference.seconds)>0 && Number.isFinite(Number(p.guide.seconds)) && Number(p.guide.seconds)>0);
function totals(rows) {
  const ref = rows.reduce((n,p)=>n+Number(p.reference.seconds),0);
  const gui = rows.reduce((n,p)=>n+Number(p.guide.seconds),0);
  return {n:rows.length,reference:ref,guide:gui,saved:ref-gui,percent:(ref-gui)/ref*100};
}
const total=totals(eligible);
const metrics={eligible_time_pairs:eligible.length,reference_seconds:total.reference,guide_seconds:total.guide,time_saved_seconds:total.saved,faster_pairs:eligible.filter(p=>Number(p.guide.seconds)<Number(p.reference.seconds)).length,slower_pairs:eligible.filter(p=>Number(p.guide.seconds)>Number(p.reference.seconds)).length,tied_pairs:eligible.filter(p=>Number(p.guide.seconds)===Number(p.reference.seconds)).length,accuracy_pairs:matched.length,reference_correct:matched.filter(p=>p.reference.correct==='true').length,guide_correct:matched.filter(p=>p.guide.correct==='true').length};
console.log(JSON.stringify({metrics,percentage:total.percent,paired_rows:matched.map(p=>({pair:p.pair_id,volunteer:p.volunteer_id,first:p.first_format,reference_seconds:p.reference.seconds,guide_seconds:p.guide.seconds,saved_seconds:p.guide.seconds===''?null:Number(p.reference.seconds)-Number(p.guide.seconds),reference_correct:p.reference.correct,guide_correct:p.guide.correct,reference_assisted:p.reference.assisted,guide_assisted:p.guide.assisted})),order_subgroups:Object.fromEntries(['reference','guide'].map(order=>[order,totals(eligible.filter(p=>p.first_format===order))])),no_assistance:totals(eligible.filter(p=>p.reference.assisted==='false'&&p.guide.assisted==='false')),assistance:{reference:matched.filter(p=>p.reference.assisted==='true').map(p=>p.pair_id),guide:matched.filter(p=>p.guide.assisted==='true').map(p=>p.pair_id)}},null,2));
function sourceFiles(dir='.') {return fs.readdirSync(dir,{withFileTypes:true}).flatMap(entry=>entry.name==='audit'?[]:entry.isDirectory()?sourceFiles(path.join(dir,entry.name)):[path.join(dir,entry.name)]);}
console.log('SOURCE_HASHES '+JSON.stringify(Object.fromEntries(sourceFiles().sort().map(file=>[file,crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex')]))));
